  async function extractBookLocations(){if(!(state.pages||[]).length)return message('Сначала разберите учебник по страницам.',true);const model=selectedTextModel();if(!model)return message('Выберите текстовую модель.',true);const btn=document.querySelector('#extractBookLocations');btn.disabled=true;btn.textContent='Ищу повторяющиеся места…';try{const source=state.pages.map(p=>({pageNumber:p.pageNumber,summary:p.summary,scene:p.scene,characters:p.characters})),prompt='Извлеки из сохранённых страниц учебника реальные повторяющиеся места действия. Не выдумывай локации, которых нет в тексте; объединяй только явно одинаковые места (например, то же кафе или дом). Верни JSON: {"locations":[{"name":"...","description":"...","referencePrompt":"Подробный визуальный промпт места: планировка, неизменные предметы, палитра и свет; без людей, текста и логотипов","sourcePages":[1,2]}]}. Страницы: '+JSON.stringify(source);const d=await window.json('chat/completions',{model,messages:[{role:'user',content:prompt}],temperature:0.2,max_tokens:3500}),parsed=parseJson(d.choices?.[0]?.message?.content);let added=0;for(const x of parsed.locations||[]){const name=String(x.name||'').trim();if(!name)continue;let l=state.locations.find(y=>y.name.trim().toLocaleLowerCase()===name.toLocaleLowerCase());if(!l){l={id:crypto.randomUUID(),name,description:'',referencePrompt:'',referenceName:'',sourcePages:[]};state.locations.push(l);added++}if(!l.description&&x.description)l.description=String(x.description);if(!l.referencePrompt&&x.referencePrompt)l.referencePrompt=String(x.referencePrompt);l.sourcePages=[...new Set([...(l.sourcePages||[]),...(x.sourcePages||[])])]}saveState();const grid=document.querySelector('#scriptLocations .location-grid');if(grid){grid.innerHTML=locationCards();loadLocationReferences()}message(`Найдено и сохранено мест: ${parsed.locations?.length||0}; новых карточек: ${added}. Стоимость ${d.usage?.cost!=null?'$'+Number(d.usage.cost).toFixed(5):'не указана'}.`)}catch(e){message('Не удалось извлечь локации: '+e.message,true)}finally{btn.disabled=false;btn.textContent='Найти места по анализу страниц'}}
  async function generateLocationReference(id){const l=state.locations.find(x=>x.id===id),model=document.querySelector('#pageImageModel')?.value;if(!l)return;if(!model)return message('Выберите модель изображений.',true);const style=state.storyBible.visual||DEFAULT_VISUAL_STYLE,prompt=(l.referencePrompt||`Create a consistent establishing reference image for the recurring location "${l.name}". ${l.description||''} Show the stable layout, furniture, colors, lighting and key landmarks. No people, text or logos.`)+'\n\nMandatory shared realistic visual style: '+style+'. Apply this even if the location prompt suggests an illustrated style.';try{const d=await window.json('images',{model,prompt}),im=d.data?.[0];if(!im?.b64_json)throw Error('Модель не вернула изображение.');const blob=new Blob([Uint8Array.from(atob(im.b64_json),ch=>ch.charCodeAt(0))],{type:im.media_type||'image/png'});await saveFile('location:'+l.id,blob);l.referenceName='Созданный AI референс';saveState();const grid=document.querySelector('#scriptLocations .location-grid');if(grid){grid.innerHTML=locationCards();loadLocationReferences()}message(`Референс места «${l.name}» создан. Стоимость ${d.usage?.cost!=null?'$'+Number(d.usage.cost).toFixed(5):'не указана'}.`)}catch(e){message('Ошибка референса локации: '+e.message,true)}}
  function mergeCharacterProfiles(profiles){if(!Array.isArray(profiles))return 0;let added=0;for(const x of profiles){const name=String(x.name||'').trim();if(!name)continue;let c=state.characters.find(v=>String(v.name||'').trim().toLocaleLowerCase()===name.toLocaleLowerCase());if(!c){c={id:crypto.randomUUID(),name:name,role:'',personality:'',speechStyle:'',visualDescription:'',referencePrompt:'',referenceName:'',source:'book-analysis'};state.characters.push(c);added++}for(const k of ['role','personality','speechStyle','visualDescription','referencePrompt'])if(!c[k]&&x[k])c[k]=String(x[k]);if(x.sourcePages&&!c.sourcePages)c.sourcePages=x.sourcePages}return added}
  async function extractBookCharacters(){if(!(state.pages||[]).length)return message('Сначала выполните анализ книги.',true);const model=selectedTextModel();if(!model)return message('Выберите текстовую модель.',true);const btn=document.querySelector('#extractBookCharacters');btn.disabled=true;btn.textContent='Извлекаю персонажей…';try{const source=state.pages.map(p=>({pageNumber:p.pageNumber,summary:p.summary,characters:p.characters,scene:p.scene}));const prompt='На основе сохранённых карточек страниц учебника собери единый список персонажей. Не добавляй тех, кто не указан явно. Объединяй варианты написания только при уверенности. Для каждого верни поля name, role, personality, speechStyle, visualDescription (стабильная внешность и одежда), referencePrompt (портретный промпт без текста и логотипов), sourcePages. Ответ только JSON вида {"characterProfiles":[{"name":"...","role":"...","personality":"...","speechStyle":"...","visualDescription":"...","referencePrompt":"...","sourcePages":[1,2]}]}. Карточки страниц:\n'+JSON.stringify(source);const d=await window.json('chat/completions',{model,messages:[{role:'user',content:prompt}],temperature:0.2,max_tokens:5000});const parsed=parseJson(d.choices?.[0]?.message?.content);const added=mergeCharacterProfiles(parsed.characterProfiles);saveState();const grid=document.querySelector('#scriptCharacters .character-grid');if(grid)grid.innerHTML=characterCards();loadCharacterAvatars();decorateDialogues();message('Карточки персонажей обновлены: добавлено '+added+'. Стоимость '+(d.usage?.cost!=null?'$'+Number(d.usage.cost).toFixed(5):'не указана')+'.')}catch(e){message('Не удалось собрать персонажей: '+e.message,true)}finally{btn.disabled=false;btn.textContent='Создать карточки из анализа учебника'}}
