  function parseJson(text){const clean=String(text||'').replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();try{return JSON.parse(clean)}catch{const a=clean.indexOf('{'),b=clean.lastIndexOf('}');if(a<0||b<=a)throw Error('Модель не вернула JSON. Попробуйте ещё раз или выберите другую модель.');return JSON.parse(clean.slice(a,b+1))}}
