  async function runPageQualityReview(i){const p=state.pages[i],model=selectedTextModel();if(!model){p.qa={passed:false,score:0,summary:'Для автоматической проверки выберите текстовую модель.',issues:[],error:'Текстовая модель не выбрана.'};renderPageQa(i);saveState();return p.qa}const result=document.querySelector('[data-page-qa-result="'+i+'"]');if(result){result.className='page-qa-result';result.textContent='Проверяю учебную цель, китайский диалог, связность и непрерывность персонажей…'}try{const page={pageNumber:p.pageNumber,summary:p.summary,learningGoal:p.learningGoal,scene:p.scene,characters:p.characters,dialogue:p.dialogue,videoPrompt:p.videoPrompt,videoPromptJson:p.videoPromptJson},prompt=`Проведи строгую редакторскую проверку короткой сцены для мультимедийного учебника HSK Course 1. Это учебник китайского языка: если learningGoal не говорит прямо, что урок обучает английскому, все произносимые реплики должны быть на нормативном мандаринском китайском, упрощёнными иероглифами. Английскую речь считать КРИТИЧЕСКОЙ ошибкой. Пиньинь и русский перевод нужны только как подсказки и никогда не озвучиваются. Проверь: (1) диалог явно тренирует слова/цель именно этой страницы и соответствует её тексту и иллюстрации; (2) есть короткий естественный диалог между указанными персонажами, с репликой каждого уместного персонажа, без добавления новых героев и целей; (3) поле dialogue — массив объектов {character,hanzi,pinyin,translation}; hanzi содержит только китайскую речь, а не описание сцены, пиньинь или перевод; (4) действие имеет ясное начало, действие и завершение и помещается в ролик до 20 секунд; (5) имена, пол, вид, внешность персонажей соответствуют карточкам и профилям; (6) видеопромпт точно задаёт действие, говорит явно «произносить только приведённые реплики на мандаринском китайском, не переводить и не добавлять английскую речь», а JSON синтаксически логичен. Если диалога нет или он на английском, обязательно верни исправленный короткий китайский dialogue, пиньинь и точный русский перевод; основывайся на учебной цели/странице, не выдумывай новые учебные факты и не копируй длинный исходный текст. Общие правила: ${storyBibleText()}. Профили персонажей: ${JSON.stringify((state.characters||[]).map(c=>({name:c.name,role:c.role,personality:c.personality,visualDescription:c.visualDescription,speechStyle:c.speechStyle})))}. Локации: ${JSON.stringify((state.locations||[]).map(l=>({name:l.name,description:l.description})))}. Карточка страницы: ${JSON.stringify(page)}. Верни только JSON: {"score":0,"passed":false,"summary":"...","issues":[{"category":"...","severity":"major|minor","message":"...","suggestion":"..."}],"dialogue":[{"character":"...","hanzi":"...","pinyin":"...","translation":"..."}],"revised":{"scene":"...","learningGoal":"...","characters":"...","videoPrompt":"...","videoPromptJson":{}}}. passed=true только при score не ниже 80, отсутствии major-проблем И валидном китайском dialogue. Не возвращай английские реплики. Не выдумывай факты учебника.`;const d=await window.json('chat/completions',{model,messages:[{role:'user',content:prompt}],temperature:0.1,max_tokens:3500}),parsed=parseJson(d.choices?.[0]?.message?.content);const score=Math.max(0,Math.min(100,Number(parsed.score)||0)),issues=Array.isArray(parsed.issues)?parsed.issues:[],dialogue=Array.isArray(parsed.dialogue)?parsed.dialogue:Array.isArray(parsed.revised?.dialogue)?parsed.revised.dialogue:null,dialogueOk=validChineseDialogue(dialogue);if(dialogueOk)p.dialogue=dialogue;else issues.push({category:'Язык речи',severity:'major',message:'Нет пригодного диалога на китайском: каждая реплика должна содержать иероглифы и не содержать латинских букв.',suggestion:'Запустите проверку ещё раз или отредактируйте поле устных реплик вручную.'});const revised=parsed.revised&&typeof parsed.revised==='object'?{...parsed.revised,...(dialogueOk?{dialogue}: {})}:dialogueOk?{dialogue}:null;const passed=Boolean(parsed.passed)&&score>=80&&dialogueOk&&!issues.some(x=>x.severity==='major');if(passed&&revised){for(const k of ['scene','learningGoal','characters','videoPrompt'])if(typeof revised[k]==='string'&&revised[k])p[k]=revised[k];if(revised.videoPromptJson)p.videoPromptJson=typeof revised.videoPromptJson==='string'?revised.videoPromptJson:JSON.stringify(revised.videoPromptJson,null,2);if(Array.isArray(revised.dialogue))p.dialogue=revised.dialogue;}p.qa={score,passed,summary:String(parsed.summary||''),issues,revised,cost:d.usage?.cost??null,checkedAt:Date.now()};saveState();renderPageQa(i);return p.qa}catch(e){p.qa={passed:false,score:0,summary:'Проверка не завершилась.',issues:[],error:e.message};saveState();renderPageQa(i);return p.qa}}
