        const emotionName=String(jsonPrompt.emotion||jsonPrompt.expression||jsonPrompt.mood||'').toLocaleLowerCase(),emotions=[...(c.emotionReferences||[])].sort((a,b)=>Number(Boolean(emotionName&&String(b.name||'').toLocaleLowerCase().includes(emotionName)))-Number(Boolean(emotionName&&String(a.name||'').toLocaleLowerCase().includes(emotionName))));
        for(const emotion of emotions){const blob=await getStoredFile('character-emotion:'+c.id+':'+emotion.id);if(blob){refs.push({type:'image_url',image_url:{url:await dataUrl(blob)}});refLabels.push('emotion '+(emotion.name||'reference')+' of '+c.name)}}
