  async function analyzeTextbook(){const file=await getBook(),model=selectedTextModel();if(!file)return message('Сначала загрузите учебник.',true);if(!model)return message('Выберите текстовую модель с поддержкой PDF и изображений.',true);const btn=document.querySelector('#analyzeWorkbook');btn.disabled=true;message(`Отправляю весь учебник (${(file.size/1024/1024).toFixed(1)} МБ). Модель вернёт страницы отдельными карточками…`);try{const prompt=`Проанализируй ВЕСЬ прикреплённый учебник от первой до последней страницы, без запроса диапазона от пользователя. Сначала определи общее количество PDF-страниц. Верни РОВНО одну карточку на каждую страницу, в исходном порядке, с фактическим номером страницы PDF (pageNumber). Не пропускай страницы: если на странице только иллюстрация, опиши её и её роль в уроке; если страница пустая/титульная, кратко отметь это. Изучи и текст, и картинки каждой страницы. Не смешивай сведения между страницами. Не копируй дословно диалоги, упражнения или иллюстрации учебника. Для каждой страницы создай: краткое содержание, учебную цель и ключевые слова, оригинальную сцену для интерактивного курса, использованных героев/их описание, промпт для оригинальной улучшенной иллюстрации, видеопромпт и редактируемый JSON видеопромпта. Известные профили героев проекта: ${(state.characters||[]).map(c=>`${c.name}: ${c.role}; характер: ${c.personality}; манера речи: ${c.speechStyle}`).join('; ')||'не заданы; выведи только персонажей, явно встречающихся в материале, новые герои должны быть самостоятельными'}. Общие правила сюжета и курса: ${storyBibleText()}. Все реплики, которые произносятся в видео, должны быть на китайском мандаринском упрощёнными иероглифами; английская речь запрещена, если английский прямо не является учебной целью. Для каждой страницы верни отдельное поле dialogue в формате массива {character,hanzi,pinyin,translation}; произносить нужно только hanzi. Пиньинь и русский перевод не озвучивать. Для каждой сцены задай ясное начало, действие, реакцию и завершение, укладывающиеся в короткий ролик до 20 секунд. Не выдумывай информацию, которой нет на конкретной странице; сомнительные места отмечай. В корень ответа дополнительно включи characterProfiles: единый список всех встречающихся в учебнике персонажей с полями name, role, personality, speechStyle, visualDescription (стабильные визуальные признаки) и referencePrompt (портретный промпт без надписей/логотипов), sourcePages. Не включай автора, редакторов и случайных упомянутых людей как персонажей, если они не участвуют в учебных сценах. Ответ только JSON: {"totalPages":число,"pages":[{"pageNumber":1,"summary":"...","learningGoal":"...","scene":"...","characters":"...","dialogue":[{"character":"...","hanzi":"...","pinyin":"...","translation":"..."}],"imagePrompt":"...","videoPrompt":"...","videoPromptJson":{"scene":"...","characters":"...","camera":"...","motion":"...","durationSeconds":8,"startFrame":"...","endFrame":"..."}}]}. Пиши компактно, чтобы охватить всю книгу. Каждый пункт должен оставаться отдельной карточкой.`;const b64=await dataUrl(file),content=[{type:'text',text:prompt}];if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf'))content.push({type:'file',file:{filename:file.name,file_data:b64}});else content.push({type:'image_url',image_url:{url:b64}});const meta=(models.chat||[]).find(m=>m.id===model),maxTokens=Math.min(60000,Number(meta?.top_provider?.max_completion_tokens||60000));const d=await window.json('chat/completions',{model,messages:[{role:'user',content}],temperature:0.2,max_tokens:maxTokens});const raw=d.choices?.[0]?.message?.content;if(typeof raw!=='string')throw Error('Модель не вернула структурированный ответ. Выберите совместимую с PDF модель.');const parsed=parseJson(raw);if(!Array.isArray(parsed.pages)||!parsed.pages.length)throw Error('Модель не вернула карточки страниц.');const newCharacterCount=mergeCharacterProfiles(parsed.characterProfiles);state.pages=mergePageAnalysisCards(state.pages,parsed.pages.map((p,i)=>({...p,id:crypto.randomUUID(),pageNumber:p.pageNumber||i+1,videoPromptJson:typeof p.videoPromptJson==='string'?p.videoPromptJson:JSON.stringify(p.videoPromptJson||{},null,2)})));state.pageRange='all';state.bookPageCount=Number(parsed.totalPages)||state.pages.length;saveState();const charGrid=document.querySelector('#scriptCharacters .character-grid');if(charGrid)charGrid.innerHTML=characterCards();loadCharacterAvatars();decorateDialogues();drawPages();const incomplete=state.bookPageCount>state.pages.length||d.choices?.[0]?.finish_reason==='length';message(`Подготовлено страниц: ${state.pages.length}. Добавлено карточек персонажей: ${newCharacterCount}.${state.bookPageCount>state.pages.length?` из ${state.bookPageCount} страниц`:''}. Стоимость ${d.usage?.cost!=null?'$'+Number(d.usage.cost).toFixed(5):'не указана'}.${incomplete?' Похоже, ответ обрезан: выберите модель с большим лимитом вывода и повторите.':''}`)}catch(e){message('Ошибка анализа учебника: '+e.message,true)}finally{btn.disabled=false}}
  function setupTextbookTabs(root){const workspace=root.querySelector('#textbookWorkspace'),pages=root.querySelector('#pageStudio'),characters=root.querySelector('#scriptCharacters'),locations=root.querySelector('#scriptLocations'),bible=root.querySelector('#storyBible'),analysis=root.querySelector('#scriptWorkbench');if(!workspace||!pages||!characters||!locations||!bible||!analysis)return;const nav=document.createElement('div');nav.className='textbook-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','Разделы мультимедийного учебника');nav.innerHTML='<button type="button" role="tab" data-textbook-tab="pages">Электронный учебник</button><button type="button" role="tab" data-textbook-tab="characters">Персонажи</button><button type="button" role="tab" data-textbook-tab="analysis">Загрузка и анализ</button>';const panels={pages:document.createElement('section'),characters:document.createElement('section'),analysis:document.createElement('section')};panels.pages.className='textbook-tab-panel';panels.pages.id='textbookPagesTab';panels.pages.setAttribute('role','tabpanel');panels.pages.append(pages);panels.characters.className='textbook-tab-panel';panels.characters.id='textbookCharactersTab';panels.characters.setAttribute('role','tabpanel');panels.characters.append(characters,locations,bible);panels.analysis.className='textbook-tab-panel';panels.analysis.id='textbookAnalysisTab';panels.analysis.setAttribute('role','tabpanel');panels.analysis.append(analysis);workspace.append(nav,panels.pages,panels.characters,panels.analysis);nav.addEventListener('click',e=>{const button=e.target.closest('[data-textbook-tab]');if(!button)return;const tab=button.dataset.textbookTab;state.activeTextbookTab=tab;for(const [key,panel] of Object.entries(panels)){const active=key===tab;panel.hidden=!active;const tabButton=nav.querySelector('[data-textbook-tab="'+key+'"]');tabButton.setAttribute('aria-selected',String(active));tabButton.tabIndex=active?0:-1}saveState()});const initial=['pages','characters','analysis'].includes(state.activeTextbookTab)?state.activeTextbookTab:'pages';nav.querySelector('[data-textbook-tab="'+initial+'"]').click()}  window.renderTextbookStudio=function(){const root=document.querySelector('#view');if(!root)return;root.innerHTML=`<div class="heading"><div><div class="eyebrow">Учебные материалы / HSK Course</div><h1>Мультимедийный учебник</h1><p>Отдельная мастерская для анализа страниц учебника, разработки персонажей и подготовки интерактивных медиа.</p></div><span class="badge">ПОСТРАНИЧНАЯ СТУДИЯ</span></div><div id="textbookWorkspace"><div class="script-work"><div id="bookAnchor" class="script-section" style="display:none"></div></div></div>`;inject();const panel=root.querySelector('#scriptWorkbench');if(panel){panel.querySelector('h2').textContent='Загрузка и анализ учебника';panel.querySelector('.script-mini').textContent='Загрузите книгу один раз: модель разберёт её целиком и создаст отдельную редактируемую карточку для каждой страницы.';panel.querySelector('label[for="workbookPdf"]').textContent='Учебник · PDF или изображение';const analyzeButton=panel.querySelector('#analyzeWorkbook');if(analyzeButton)analyzeButton.textContent='Разобрать весь учебник по страницам ↗';panel.querySelector('#workbookPages')?.closest('.script-field')?.remove();panel.querySelector('#variantCount')?.closest('.script-field')?.remove();panel.querySelector('#compareModels')?.closest('.model-compare-box')?.remove();panel.querySelector('#modelComparisons')?.remove();panel.querySelector('#candidateList')?.remove();panel.querySelector('#exportWorkbench')?.remove();panel.querySelector('.script-help')?.remove()}root.querySelector('.character-library h2').textContent='Персонажи учебника';const extractCharacters=root.querySelector('#extractBookCharacters');if(extractCharacters)extractCharacters.style.display='inline-flex';root.querySelector('.character-library .script-mini').textContent='Создайте единые профили и референсы героев, чтобы использовать их при подготовке изображений и видео.';root.querySelector('.storyboard')?.remove();setupTextbookTabs(root)};
  document.addEventListener('click',e=>{const qa=e.target.closest?.('[data-page-qa-action]');if(qa){const i=Number(qa.dataset.index),p=state.pages[i];if(!p)return;if(qa.dataset.pageQaAction==='continue'){p.qa={...(p.qa||{}),approvedOverride:true};saveState();generatePageVideo(i,true);return}if(qa.dataset.pageQaAction==='apply'){const r=p.qa?.revised;if(!r)return;for(const k of ['scene','learningGoal','characters','videoPrompt'])if(typeof r[k]==='string'&&r[k])p[k]=r[k];if(Array.isArray(r.dialogue))p.dialogue=r.dialogue;if(r.videoPromptJson)p.videoPromptJson=typeof r.videoPromptJson==='string'?r.videoPromptJson:JSON.stringify(r.videoPromptJson,null,2);p.qa=null;saveState();drawPages();message('Рекомендации применены. Проверьте текст и запустите повторную проверку.')}return}const turn=e.target.closest?.('[data-page-turn]');if(turn){state.currentPageIndex=Math.max(0,Math.min((state.pages||[]).length-1,(Number(state.currentPageIndex)||0)+Number(turn.dataset.pageTurn)));saveState();drawPages();return}const pick=e.target.closest?.('[data-page-image-select]');if(pick){const card=pick.closest('[data-page-card]'),i=Number(card?.dataset.pageCard),p=state.pages[i];if(p){p.activeImageId=pick.dataset.pageImageSelect;saveState();loadPageMedia(i);renderElectronicPage(i)}return}const b=e.target.closest?.('[data-page-action]');if(b){const card=b.closest('[data-page-card]'),i=Number(card?.dataset.pageCard),p=state.pages[i];if(!p)return;const action=b.dataset.pageAction;if(action==='image')generatePageImage(i);if(action==='video'){if(p.videoReady&&!window.confirm('Пересоздать клип страницы '+p.pageNumber+'? Новое видео заменит текущее везде, включая веб-страницу, а обложка будет взята из нового видео.'))return;generatePageVideo(i)}if(action==='delete'){if(!window.confirm('Удалить карточку страницы '+p.pageNumber+'? Сценарий и медиа этой страницы будут удалены.'))return;const id=p.id,keys=['page-ref:'+id,'page-video:'+id,'page-source-image:'+id,'page-frame:first_frame:'+id,'page-frame:last_frame:'+id,'page-image:'+id,...(p.images||[]).map(entry=>entry.key||'page-image:'+id+':'+entry.id)];state.pages.splice(i,1);state.currentPageIndex=Math.min(i,(state.pages||[]).length-1);saveState();drawPages();Promise.all(keys.map(deleteFile)).catch(error=>message('Не удалось удалить все файлы страницы: '+error.message,true))}if(action==='remove-ref')Promise.all(['page-ref:'+p.id,'page-frame:first_frame:'+p.id,'page-frame:last_frame:'+p.id].map(deleteFile)).then(()=>loadPageMedia(i));return}if(e.target.closest?.('#exportInteractive'))exportInteractive()},true);  document.addEventListener('input',e=>{const el=e.target.closest?.('[data-ebook-block],[data-ebook-dialogue],[data-programmatic-line]');if(!el)return;const card=el.closest('[data-page-card]'),p=state.pages[Number(card?.dataset.pageCard)],field=el.dataset.programmaticField||el.dataset.ebookField||'text';if(!p)return;const value=el.innerText??el.textContent,clone=p.programmaticCloneDraft||p.programmaticClone;if(el.hasAttribute('data-programmatic-line')){const line=clone?.lines[Number(el.dataset.programmaticLine)];if(line)line[field==='original'?'original':field]=value}else if(field==='overlayText'){const overlays=p.translationOverlayDraft?.segments||p.translationOverlays||[];if(overlays[Number(el.dataset.ebookBlock)])overlays[Number(el.dataset.ebookBlock)].russian=value}else if(el.hasAttribute('data-ebook-dialogue')){const line=p.dialogue?.[Number(el.dataset.ebookDialogue)];if(line)line[field]=value}else{const block=p.electronicBlocks?.[Number(el.dataset.ebookBlock)];if(block)block[field]=value}saveState()},true);
  document.addEventListener('click',e=>{const language=e.target.closest?.('[data-ebook-language]');if(language){const card=language.closest('[data-page-card]'),i=Number(card?.dataset.pageCard),p=state.pages[i],mode=language.dataset.ebookLanguage;if(!p||!['original','russian'].includes(mode))return;p.electronicLanguageMode=mode;if(p.programmaticCloneDraft||p.programmaticClone){saveState();renderElectronicPage(i);return}const root=card.querySelector('[data-electronic-page-preview="'+i+'"]');root?.querySelector('.ebook-page-content')?.setAttribute('data-language-mode',mode);root?.querySelectorAll('[data-ebook-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ebookLanguage===mode)));fitSourceBlocks(root);saveState();return}const action=e.target.closest?.('[data-ebook-action]');if(action){const card=action.closest('[data-page-card]'),i=Number(card?.dataset.pageCard),p=state.pages[i];if(!p)return;const kind=action.dataset.ebookAction;if(kind==='review-clone'){reviewSavedClone(i);return}if(kind==='clone'){buildProgrammaticClone(i);return}if(kind==='apply-programmatic-clone'){if(!p.programmaticCloneDraft)return;const clone=p.programmaticCloneDraft;if(p.programmaticClone)p.previousProgrammaticClone=p.programmaticClone;p.programmaticClone=clone;p.programmaticCloneDraft=null;if(clone.kind==='pdf-raster-fidelity'){delete p.previousProgrammaticCloneDraft;delete p.previousElectronicBlocksAreSource;delete p.previousElectronicLanguageMode;delete p.previousRasterOverlayCloneId}p.electronicLanguageMode=clone.kind==='pdf-raster-fidelity'?(p.rasterOverlayCloneId===clone.createdAt?'russian':'original'):'russian';saveState();renderElectronicPage(i);message('Программная копия страницы применена. Исходный PDF и разбор страницы сохранены.');return}if(kind==='discard-programmatic-clone'){const clone=p.programmaticCloneDraft;p.programmaticCloneDraft=p.previousProgrammaticCloneDraft||null;delete p.previousProgrammaticCloneDraft;if(clone?.kind==='pdf-raster-fidelity'){if(Object.prototype.hasOwnProperty.call(p,'previousElectronicBlocksAreSource'))p.electronicBlocksAreSource=Boolean(p.previousElectronicBlocksAreSource);p.electronicLanguageMode=p.previousElectronicLanguageMode||'original';p.rasterOverlayCloneId=p.previousRasterOverlayCloneId||null}delete p.previousElectronicBlocksAreSource;delete p.previousElectronicLanguageMode;delete p.previousRasterOverlayCloneId;p.suppressOverlayDraft=true;saveState();renderElectronicPage(i);message('Черновик клона отклонён. Сохранённая версия страницы не изменилась.');return}if(kind==='apply-overlay-draft'){if(!p.translationOverlayDraft?.segments?.length)return;p.translationOverlays=p.translationOverlayDraft.segments;p.translationOverlayMode=true;p.translationOverlaySourceFingerprint=p.translationOverlayDraft.pdfSourceFingerprint||null;if(p.translationOverlaySourceFingerprint)p.rasterTranslationOverlayVersion=1;p.translationOverlayDraft=null;p.electronicLanguageMode='russian';saveState();renderElectronicPage(i);message('Русские вставки применены. Китайский текст и фон PDF оставлены без изменений.');return}if(kind==='discard-overlay-draft'){p.translationOverlayDraft=null;saveState();renderElectronicPage(i);message('Черновик отклонён. Сохранённая версия страницы не изменилась.');return}p.electronicBlocks=ensureElectronicBlocks(p);if(kind==='add-text')p.electronicBlocks.push({type:'paragraph',text:'Нажмите и введите текст страницы'});if(kind==='add-vocabulary')p.electronicBlocks.push({type:'vocabulary',chinese:'中文',pinyin:'Pīnyīn',russian:'Перевод на русский'});if(kind==='add-video')p.electronicBlocks.push({type:'video'});saveState();renderElectronicPage(i);return}if(e.target.closest?.('#exportInteractiveHtml')){exportInteractiveHtml();return}},true);  const observer=new MutationObserver(()=>{inject();decorateDialogues();fillCompareModels()});observer.observe(document.querySelector('#view'),{childList:true,subtree:true});
